using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class KeyframeCanvasOperations
{
    public void gui_input(Control owner,InputEvent e)
    {
        var actor=Actor(owner);if(actor==null)return;var selected=Selected(owner);var tracks=displayed_tracks(owner);if(e is InputEventKey key&&key.Pressed){if(key.Keycode is Key.Delete or Key.Backspace&&selected.Count>0){owner.EmitSignal("delete_requested",selected.Duplicate());selected.Clear();owner.EmitSignal("selection_changed");owner.AcceptEvent();}else if(key.Keycode==Key.A&&key.CtrlPressed){selected.Clear();foreach(var track in tracks)foreach(var item in track.As<Resource>().Get("keys").AsGodotArray())selected.Add(item.As<Resource>().Get("id"));owner.EmitSignal("selection_changed");owner.QueueRedraw();owner.AcceptEvent();}else if(key.Keycode is Key.Left or Key.Right&&selected.Count>0){owner.EmitSignal("move_requested",selected.Duplicate(),(key.Keycode==Key.Right?1:-1)*(key.ShiftPressed?1.0:.1));owner.AcceptEvent();}}if(e is not InputEventMouseButton button||!button.Pressed||button.ButtonIndex!=MouseButton.Left)return;owner.GrabFocus();var timeline=Timeline(owner);var clip=_timeline.clip_for_actor_id(Model(owner),actor.Get("id").AsString());if(clip==null)return;if(!Overlay(owner)&&owner.Get("show_ruler").AsBool()&&button.Position.Y<Header&&button.Position.X>=LabelWidth){if(timeline.Get("split_tool").AsBool()&&button.Position.Y>=27){_timeline.split_clip(Model(owner),clip.Get("id").AsString(),_canvas.time_at(timeline,button.Position.X));owner.AcceptEvent();return;}owner.Set("_scrubbing",true);owner.Set("_scrub_origin",timeline.Get("playhead"));timeline.EmitSignal("time_selected",_canvas.snapped_playhead(timeline,_canvas.time_at(timeline,button.Position.X),button.ShiftPressed,true));owner.AcceptEvent();return;}string hit="";var overlay=overlay_rect(owner);float distance=Overlay(owner)?Math.Min(10,overlay.Size.Y/(tracks.Count+1)*.5f):10;for(int row=0;row<tracks.Count;row++)foreach(var item in tracks[row].As<Resource>().Get("keys").AsGodotArray()){var frame=item.As<Resource>();float next=Position(owner,clip,frame,row,tracks.Count,overlay).DistanceTo(button.Position);if(button.Position.X>=LabelWidth&&next<distance){hit=frame.Get("id").AsString();distance=next;}}if(hit.Length==0){if(!Overlay(owner)&&!owner.Get("ruler_only").AsBool()&&button.Position.X>=LabelWidth){owner.Set("box_selecting",true);owner.Set("_box_start",button.Position);owner.Set("_box_end",button.Position);var before=owner.Get("_box_base").AsGodotArray();before.Clear();foreach(var id in selected)before.Add(id);update_box(owner,button.ShiftPressed,button.CtrlPressed);owner.EmitSignal("interaction_changed","Esc cancels box select • Shift adds • Ctrl removes");}}else if(button.CtrlPressed&&selected.Contains(hit))selected.Remove(hit);else{if(!button.ShiftPressed&&!button.CtrlPressed&&!selected.Contains(hit))selected.Clear();selected.Remove(hit);selected.Add(hit);owner.Set("_dragging",true);owner.Set("_drag_origin",button.GlobalPosition.X);owner.Set("_delta",0.0);var times=owner.Get("_original_times").AsGodotDictionary();times.Clear();foreach(var id in selected){var frame=_timeline.keyframe_for_id(actor,id.AsString());if(frame!=null)times[id]=frame.Get("time");}owner.EmitSignal("interaction_changed","Esc cancels keyframe drag • Shift disables snap");}owner.EmitSignal("selection_changed");owner.QueueRedraw();owner.AcceptEvent();
    }
    public void input(Control owner,InputEvent e)
    {
        var timeline=Timeline(owner);if(owner.Get("box_selecting").AsBool()){if(e is InputEventMouseMotion motion){owner.Set("_box_end",owner.GetGlobalTransform().AffineInverse()*motion.Position);update_box(owner,motion.ShiftPressed,motion.CtrlPressed);}else if(e is InputEventMouseButton button&&button.ButtonIndex==MouseButton.Left&&!button.Pressed){owner.Set("_box_end",owner.GetGlobalTransform().AffineInverse()*button.Position);update_box(owner,button.ShiftPressed,button.CtrlPressed);owner.Set("box_selecting",false);owner.EmitSignal("interaction_changed","");owner.QueueRedraw();}else if(e is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape)cancel_drag(owner);else return;owner.GetViewport().SetInputAsHandled();return;}if(Overlay(owner)&&!timeline.Get("split_tool").AsBool()&&owner.IsVisibleInTree()&&overlay_rect(owner).HasArea()&&e is InputEventMouseButton click&&click.Pressed&&click.ButtonIndex==MouseButton.Left){var local=owner.GetGlobalTransform().AffineInverse()*click.Position;var tracks=displayed_tracks(owner);var actor=Actor(owner);var clip=actor!=null?_timeline.clip_for_actor_id(Model(owner),actor.Get("id").AsString()):null;var overlay=overlay_rect(owner);if(clip!=null)for(int row=0;row<tracks.Count;row++)foreach(var item in tracks[row].As<Resource>().Get("keys").AsGodotArray()){var frame=item.As<Resource>();if(local.X>=LabelWidth&&overlay.HasPoint(local)&&Position(owner,clip,frame,row,tracks.Count,overlay).DistanceTo(local)<Math.Min(10,overlay.Size.Y/(tracks.Count+1)*.5f)){using var forwarded=(InputEventMouseButton)click.Duplicate();forwarded.Position=local;gui_input(owner,forwarded);owner.GetViewport().SetInputAsHandled();return;}}}if(owner.Get("_scrubbing").AsBool()){if(e is InputEventMouseMotion motion){var local=owner.GetGlobalTransform().AffineInverse()*motion.Position;timeline.EmitSignal("time_selected",_canvas.snapped_playhead(timeline,_canvas.time_at(timeline,local.X),motion.ShiftPressed,true));}else if(e is InputEventMouseButton button&&!button.Pressed&&button.ButtonIndex==MouseButton.Left)owner.Set("_scrubbing",false);else if(e is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape){owner.Set("_scrubbing",false);timeline.EmitSignal("time_selected",owner.Get("_scrub_origin"));}else return;owner.GetViewport().SetInputAsHandled();return;}if(!owner.Get("_dragging").AsBool())return;var draggedActor=Actor(owner);var draggedClip=draggedActor!=null?_timeline.clip_for_actor_id(Model(owner),draggedActor.Get("id").AsString()):null;if(draggedClip==null){cancel_drag(owner);return;}
        if(e is InputEventMouseMotion move){double delta=(move.Position.X-owner.Get("_drag_origin").AsDouble())/timeline.Get("pixels_per_second").AsDouble();if(timeline.Get("snap_enabled").AsBool()&&!move.ShiftPressed)delta=Mathf.Snapped(delta,.1);if(timeline.Get("magnet_enabled").AsBool()&&!move.ShiftPressed){var moving=new GArray();foreach(var source in owner.Get("_original_times").AsGodotDictionary().Values)moving.Add(draggedClip.Get("start_time").AsDouble()+(source.AsDouble()-draggedClip.Get("source_offset").AsDouble())/draggedClip.Get("playback_speed").AsDouble());delta=_canvas.magnetic_delta(timeline,delta,moving,new GArray(),Selected(owner),!Overlay(owner),true);}owner.Set("_delta",delta);owner.EmitSignal("move_preview_requested",Selected(owner).Duplicate(),delta);owner.QueueRedraw();owner.GetViewport().SetInputAsHandled();}else if(e is InputEventMouseButton release&&release.ButtonIndex==MouseButton.Left&&!release.Pressed){owner.Set("_dragging",false);double delta=owner.Get("_delta").AsDouble();if(!Mathf.IsZeroApprox(delta))owner.EmitSignal("move_requested",Selected(owner).Duplicate(),delta);End(owner);owner.GetViewport().SetInputAsHandled();}else if(e is InputEventKey escape&&escape.Pressed&&escape.Keycode==Key.Escape){owner.Set("_dragging",false);End(owner);owner.GetViewport().SetInputAsHandled();}
    }
    private static void End(Control owner){owner.Set("_delta",0.0);owner.Get("_original_times").AsGodotDictionary().Clear();owner.EmitSignal("interaction_changed","");owner.QueueRedraw();}
}
